CREATE OR REPLACE VIEW "vw_000_forex_prices" AS
SELECT current_datetime, current_prices
FROM     forex_price LIMIT 1000;

CREATE OR REPLACE VIEW "vw_000_fx_quotes" AS
SELECT id, timestamp, code, type, bid, ask
FROM     fx_quotes LIMIT 1000;

CREATE OR REPLACE VIEW "vw_117_tbl_model_signal_net" AS
SELECT tbl_model_signal_net.*
FROM     tbl_model_signal_net;

/* Trades created within the last 10 minutes
-WHERE  (tsql_compat.datediff(SECOND, created, CURRENT_TIMESTAMP) <= 600)*/
CREATE OR REPLACE VIEW "vwCombined_trades_open_restricted" AS
SELECT guid, model, product, product_type, created, last_update, signal, entry_price, latest_price, entry_price2, latest_price2, commission, target_profit, target_loss, rl_signal, tradeable, net_return, alt_net_return, pos_net_return_buy, 
                  pos_net_return_sell, trade_diff, RL_Check, percent_profit, percent_loss, buy_count, sell_count, linked, int_profit, int_profit_time, trade_quantity, min_net_return, min_net_return_time, max_net_return, max_net_return_time
FROM     combined_trades_open;
